    double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
        double h = (b - a) / 2.0;
        double fa = f(a);
        double fb = f(b);
        double fm = f((a + b) / 2.0);
        double T1 = (h / 2.0) * (fa + fb);
        double T2 = (h / 2.0) * (fa + 2 * fm + fb);
        while (std::abs(T2 - T1) > precision) {
            h /= 2.0;
            fa = f(a);
            fb = f(b);
            fm = f((a + b) / 2.0);
            T1 = T2;
            T2 = (h / 2.0) * (fa + 2 * fm + fb);
        }
        return T2;
    }
